('01M4D6BGDHHH34ZCME00JRB732', '01M4D6BGDG5SF3RJRSJ1NDCWY5', NULL, 'strategy', 'Strategy', 'استراتيجية', 'A high level document that sets long term national or institutional direction and goals.', 'وثيقة رفيعة المستوى تحدد التوجه والأهداف الوطنية أو المؤسسية على المدى الطويل.', 10, 1),
('01M4D6BGDHD6RDS39A7YAESG44', '01M4D6BGDG5SF3RJRSJ1NDCWY5', NULL, 'policy', 'Policy', 'سياسة', 'A formal statement of principles guiding decisions and actions in a specific domain.', 'بيان رسمي للمبادئ الموجهة للقرارات والإجراءات في مجال محدد.', 20, 1),
('01M4D6BGDH5E8MXQBVA211ZZ1Y', '01M4D6BGDG5SF3RJRSJ1NDCWY5', NULL, 'guideline', 'Guideline', 'دليل إرشادي', 'A practical document that provides recommended procedures or standards for carrying out a task.', 'وثيقة عملية تقدم إجراءات أو معايير موصى بها لإنجاز مهمة معينة.', 30, 1),
('01M4D6BGDHYBDGBNC43EZ2DHWX', '01M4D6BGDG5SF3RJRSJ1NDCWY5', NULL, 'study', 'Study', 'دراسة', 'An in depth analytical work examining a particular issue or research question.', 'عمل تحليلي معمق يتناول قضية أو سؤالاً بحثياً محدداً.', 40, 1),
('01M4D6BGDJXKNWBRFRZTB7RJ7X', '01M4D6BGDG5SF3RJRSJ1NDCWY5', NULL, 'report', 'Report', 'تقرير', 'A structured document presenting findings, progress, or analysis on a specific subject.', 'وثيقة منظمة تعرض النتائج أو التقدم المحرز أو التحليل المتعلق بموضوع محدد.', 50, 1),
('01M4D6BGDJ0KRHJVQMBTS1WWBY', '01M4D6BGDG5SF3RJRSJ1NDCWY5', NULL, 'statistical_release', 'Statistical Release', 'إصدار إحصائي', 'An official publication presenting statistical results and indicators for a defined reference period.', 'إصدار رسمي يعرض النتائج والمؤشرات الإحصائية لفترة مرجعية محددة.', 60, 1),
('01M4D6BGDJQPBET9WVHKS066PW', '01M4D6BGDG5SF3RJRSJ1NDCWY5', NULL, 'dataset', 'Dataset', 'مجموعة بيانات', 'A structured collection of data made available for analysis or reuse.', 'مجموعة منظمة من البيانات متاحة للتحليل أو إعادة الاستخدام.', 70, 1),
('01M4D6BGDJQZWAS8Q4GNB7QEES', '01M4D6BGDG5SF3RJRSJ1NDCWY5', NULL, 'presentation', 'Presentation', 'عرض تقديمي', 'A visual slide based document prepared to communicate information to an audience.', 'وثيقة مرئية بصيغة شرائح تعد لتوصيل المعلومات إلى جمهور مستهدف.', 80, 1),
('01M4D6BGDJWP30PS6H6EACTT2C', '01M4D6BGDG5SF3RJRSJ1NDCWY5', NULL, 'minutes', 'Minutes', 'محضر اجتماع', 'An official written record of discussions and decisions made during a meeting.', 'سجل مكتوب رسمي للمناقشات والقرارات الصادرة خلال اجتماع ما.', 90, 1),
('01M4D6BGDKAAH9M3Z5BBNTP1QM', '01M4D6BGDG5SF3RJRSJ1NDCWY5', NULL, 'template', 'Template', 'نموذج', 'A reusable standard format designed to structure the preparation of similar documents.', 'قالب معياري قابل لإعادة الاستخدام يهدف إلى تنظيم إعداد وثائق مماثلة.', 100, 1),
