('01M4D6C56YB3N77GK8PW9ADACJ', 'hr@enviroai.demo', '$2b$10$i42GWFXMkdVz/A/sso2u6uijx9eibc4OolZWAgM6T7wInU95TIKdi', 'Noof Al-Suwaidi', 'نوف السويدي', NULL, 'aqua', '01M4D6BGEN9QDGX3095WSWMVDJ', '01M4D6C56W6X8Q9RFT3QA0FZNQ', 3, 'all', 'en', 'western', 0, NULL, 'Head of People and Knowledge Continuity', 'رئيسة وحدة الأشخاص واستمرارية المعرفة', NULL, '2026-10-08T07:24:20.138Z', '2026-10-08T07:24:20.138Z', NULL, NULL, 0, NULL, '2026-10-08T07:24:20.138Z', NULL, NULL, NULL);
INSERT INTO "word_of_day" ("id", "date", "kind", "text_en", "text_ar", "attribution_en", "attribution_ar", "source_ref") VALUES
('01M4D6BHRDWK95E312ACHSG9Q4', NULL, 'quote', 'Good environmental decisions start with data that people trust.', 'القرارات البيئية الجيدة تبدأ ببيانات يثق بها الناس.', 'Programme Office guiding principle', 'مبدأ توجيهي لمكتب البرنامج', 'Programme Office demo copy'),
('01M4D6BHRDS4BSWCEDV3DH1CEH', NULL, 'quote', 'Saudi Vision 2030 is our compass; the National Environment Strategy is how we turn it into measurable progress.', 'رؤية السعودية 2030 هي بوصلتنا، والاستراتيجية الوطنية للبيئة هي الطريق لتحويلها إلى تقدم قابل للقياس.', 'Programme Office guiding principle', 'مبدأ توجيهي لمكتب البرنامج', 'Programme Office demo copy'),
('01M4D6BHRD33G78N0AGYW4YW2T', NULL, 'quote', 'Statistics without context are just numbers; our task is to turn numbers into understanding.', 'الإحصاءات بلا سياق مجرد أرقام، ومهمتنا تحويل الأرقام إلى فهم.', 'Programme Office guiding principle', 'مبدأ توجيهي لمكتب البرنامج', 'Programme Office demo copy'),
('01M4D6BHRE5FM95RNQ7HHASV6C', NULL, 'quote', 'An institution that measures itself honestly can improve itself continuously.', 'المؤسسة التي تقيس نفسها بصدق قادرة على التحسن باستمرار.', 'Programme Office guiding principle', 'مبدأ توجيهي لمكتب البرنامج', 'Programme Office demo copy'),
('01M4D6BHRE15EK8BJZ6K6ZPZDF', NULL, 'quote', 'Success is judged not by the plans we wrote, but by the outcomes delivered for water, land and air.', 'يُقاس النجاح لا بالخطط التي كتبناها، بل بالنتائج التي تحققت للمياه والأرض والهواء.', 'Programme Office guiding principle', 'مبدأ توجيهي لمكتب البرنامج', 'Programme Office demo copy'),
('01M4D6BHREXX4VVW8Z6YEDH0MQ', NULL, 'quote', 'Every entity that shares its data responsibly makes the whole sector smarter.', 'كل جهة تشارك بياناتها بمسؤولية تجعل القطاع كله أكثر ذكاءً.', 'Programme Office guiding principle', 'مبدأ توجيهي لمكتب البرنامج', 'Programme Office demo copy'),
('01M4D6BHRENXWX5CTGK0XAH80P', NULL, 'quote', 'Planning is a continuous act of listening to evidence and adjusting course.', 'وضع الخطط عمل مستمر من الإصغاء إلى الأدلة وتعديل المسار.', 'Programme Office guiding principle', 'مبدأ توجيهي لمكتب البرنامج', 'Programme Office demo copy'),
('01M4D6BHREK1S83EWNAVSD4H38', NULL, 'quote', 'We owe the public transparency in how environmental indicators are measured and reported.', 'نحن مدينون للجمهور بالشفافية في كيفية قياس المؤشرات البيئية والإبلاغ عنها.', 'Programme Office guiding principle', 'مبدأ توجيهي لمكتب البرنامج', 'Programme Office demo copy'),
('01M4D6BHRENTYN6B87QD4XSSQ9', NULL, 'quote', 'The strength of a monitoring system is the trust that institutions and citizens place in it.', 'قوة منظومة الرصد هي الثقة التي تضعها فيها المؤسسات والمواطنون.', 'Programme Office guiding principle', 'مبدأ توجيهي لمكتب البرنامج', 'Programme Office demo copy'),
('01M4D6BHRE92FBJEZYNPCY65G0', NULL, 'quote', 'Every drop saved is a decision made well upstream.', 'كل لتر مياه نوفره هي قرار أُحسن اتخاذه في وقت مبكر.', 'Programme Office guiding principle', 'مبدأ توجيهي لمكتب البرنامج', 'Programme Office demo copy'),
('01M4D6BHRE747PEPX68M4XCKWW', NULL, 'quote', 'Foresight is not predicting the future with certainty; it is preparing for several possible futures.', 'الاستشراف ليس التنبؤ بالمستقبل بيقين، بل الاستعداد لعدة مستقبلات ممكنة.', 'Programme Office guiding principle', 'مبدأ توجيهي لمكتب البرنامج', 'Programme Office demo copy'),
('01M4D6BHRE4HF5ANTDVX52H6JG', NULL, 'quote', 'Shared data standards are the quiet infrastructure behind every dashboard and every decision.', 'معايير البيانات المشتركة هي البنية الهادئة وراء كل لوحة مؤشرات وكل قرار.', 'Programme Office guiding principle', 'مبدأ توجيهي لمكتب البرنامج', 'Programme Office demo copy'),
('01M4D6BHREPW18DQ4F72N9B2CG', NULL, 'quote', 'We invest in monitoring and surveys because good decisions require good numbers.', 'نستثمر في الرصد والمسوح لأن القرارات الجيدة تتطلب أرقاماً جيدة.', 'Programme Office guiding principle', 'مبدأ توجيهي لمكتب البرنامج', 'Programme Office demo copy'),
('01M4D6BHRF05R4BSE3C54B361H', NULL, 'quote', 'Environmental protection and economic growth are two sides of the same commitment.', 'حماية البيئة والنمو الاقتصادي وجهان لالتزام واحد.', 'Programme Office guiding principle', 'مبدأ توجيهي لمكتب البرنامج', 'Programme Office demo copy'),
('01M4D6BHRFE5EZDPM2Z09K9GT9', NULL, 'quote', 'A knowledge-based sector begins with institutional memory that is easy to search and trust.', 'القطاع القائم على المعرفة يبدأ بذاكرة مؤسسية يسهل البحث فيها والوثوق بها.', 'Programme Office guiding principle', 'مبدأ توجيهي لمكتب البرنامج', 'Programme Office demo copy'),
('01M4D6BHRFN3PXK67MTVBTSQWT', NULL, 'quote', 'Every indicator we publish is a promise of accountability.', 'كل مؤشر ننشره هو وعد بالمساءلة.', 'Programme Office guiding principle', 'مبدأ توجيهي لمكتب البرنامج', 'Programme Office demo copy'),
('01M4D6BHRF6K2SK26WAWEK8ZEE', NULL, 'quote', 'Our ambition is that no environmental policy is made without first consulting the evidence.', 'طموحنا ألا تُصاغ سياسة بيئية دون الاطلاع أولاً على الأدلة.', 'Programme Office guiding principle', 'مبدأ توجيهي لمكتب البرنامج', 'Programme Office demo copy'),
('01M4D6BHRFMNKZ2W2JS95BT7TV', NULL, 'quote', 'The Programme Office exists to connect strategy, data and delivery in one continuous cycle.', 'يوجد مكتب البرنامج ليربط الاستراتيجية والبيانات والتنفيذ في دورة واحدة متصلة.', 'Programme Office guiding principle', 'مبدأ توجيهي لمكتب البرنامج', 'Programme Office demo copy'),
('01M4D6BHRFKHJ56ATCYZSD0D3R', NULL, 'quote', 'Compliance is easier when requirements are clear, current and easy to find.', 'الامتثال أيسر حين تكون المتطلبات واضحة ومحدّثة ويسهل الوصول إليها.', 'Programme Office guiding principle', 'مبدأ توجيهي لمكتب البرنامج', 'Programme Office demo copy'),
('01M4D6BHRF3D17YZM50FD6P5WN', NULL, 'quote', 'We ask every delivery team to treat monitoring and evaluation not as a burden but as a compass.', 'نطلب من كل فريق تنفيذ أن ينظر إلى المتابعة والتقييم بوصفهما بوصلة لا عبئاً.', 'Programme Office guiding principle', 'مبدأ توجيهي لمكتب البرنامج', 'Programme Office demo copy'),
('01M4D6BHRFFVA1ZF39SJ6EAJZT', NULL, 'fact', 'The National Environment Strategy delivery plan in this demo is organised into seven environment themes mapped to Saudi Vision 2030.', 'تنظم خطة تنفيذ الاستراتيجية الوطنية للبيئة في هذا العرض في سبعة محاور بيئية مرتبطة برؤية السعودية 2030.', NULL, NULL, NULL),
('01M4D6BHRFGZ3736K195MQ5Z74', NULL, 'fact', 'Saudi Vision 2030 rests on three pillars: a Vibrant Society, a Thriving Economy and an Ambitious Nation.', 'ترتكز رؤية السعودية 2030 على ثلاث ركائز: مجتمع حيوي واقتصاد مزدهر ووطن طموح.', NULL, NULL, NULL),
('01M4D6BHRFXAN7CXXV2M3RXY1M', NULL, 'fact', 'The Saudi Green Initiative includes a target to protect 30 percent of land and sea areas by 2030.', 'تتضمن مبادرة السعودية الخضراء مستهدفاً لحماية 30 بالمئة من المساحات البرية والبحرية بحلول 2030.', NULL, NULL, NULL),
('01M4D6BHRGN7SGC4KVCQ39T2CW', NULL, 'fact', 'The Saudi Green Initiative targets 50 percent of electricity from renewable sources by 2030.', 'تستهدف مبادرة السعودية الخضراء توليد 50 بالمئة من الكهرباء من مصادر متجددة بحلول 2030.', NULL, NULL, NULL),
('01M4D6BHRG0RG4R20HJ8DFV9AE', NULL, 'fact', 'The Kingdom announced in 2021 an ambition to reach net zero emissions by 2060 through a circular carbon economy approach.', 'أعلنت المملكة عام 2021 طموحها لبلوغ الحياد الصفري للانبعاثات بحلول 2060 عبر نهج الاقتصاد الدائري للكربون.', NULL, NULL, NULL),
('01M4D6BHRGQH12FX3W5K6NBRRX', NULL, 'fact', 'The Saudi Green Initiative aims to reduce emissions by 278 million tonnes of CO2e annually by 2030.', 'تهدف مبادرة السعودية الخضراء إلى خفض الانبعاثات بمقدار 278 مليون طن مكافئ من ثاني أكسيد الكربون سنوياً بحلول 2030.', NULL, NULL, NULL),
('01M4D6BHRGPP55HNEXB3TJQKZM', NULL, 'fact', 'The Middle East Green Initiative aims to plant 50 billion trees across the region.', 'تهدف مبادرة الشرق الأوسط الأخضر إلى زراعة 50 مليار شجرة في المنطقة.', NULL, NULL, NULL),
('01M4D6BHRGPTBJ13C4GTN3GJX4', NULL, 'fact', 'The Saudi Green Initiative includes a target to plant 10 billion trees in the Kingdom.', 'تتضمن مبادرة السعودية الخضراء مستهدفاً لزراعة 10 مليارات شجرة في المملكة.', NULL, NULL, NULL),
('01M4D6BHRGXVT7BAPKC5W5G5AK', NULL, 'fact', 'The Ministry of Environment, Water and Agriculture (MEWA) leads water, environment and agriculture policy.', 'تتولى وزارة البيئة والمياه والزراعة قيادة سياسات المياه والبيئة والزراعة.', NULL, NULL, NULL),
('01M4D6BHRGGKPQ42WQAQAZ6KSB', NULL, 'fact', 'The National Center for Environmental Compliance (NCEC) is the national environmental compliance and enforcement body.', 'المركز الوطني للرقابة على الالتزام البيئي هو الجهة الوطنية للامتثال والإنفاذ البيئي.', NULL, NULL, NULL),
('01M4D6BHRGQBNTJJN9NVA8A0FX', NULL, 'fact', 'The National Center for Wildlife (NCW) manages biodiversity and protected areas.', 'يتولى المركز الوطني للحياة الفطرية إدارة التنوع الأحيائي والمحميات.', NULL, NULL, NULL),
('01M4D6BHRGJCMP63CG5WD6B055', NULL, 'fact', 'The National Center for Vegetation Cover Development and Combating Desertification (NCVC) works on vegetation cover and desertification.', 'يعمل المركز الوطني لتنمية الغطاء النباتي ومكافحة التصحر على الغطاء النباتي والتصحر.', NULL, NULL, NULL),
('01M4D6BHRGDJZTE6KCGF5VJPWQ', NULL, 'fact', 'The National Center for Waste Management (MWAN) regulates and develops the waste sector.', 'ينظم المركز الوطني لإدارة النفايات قطاع النفايات ويطوره.', NULL, NULL, NULL),
('01M4D6BHRGP9KCXYZ13CMB8FE9', NULL, 'fact', 'The Source Library in EnviroAI is built from a databank of public Saudi and international sources on environment, water and agriculture.', 'بنيت مكتبة المصادر في EnviroAI من قاعدة مصادر عامة سعودية ودولية عن البيئة والمياه والزراعة.', NULL, NULL, NULL),
('01M4D6BHRHYYWYPSJDS2EF3E57', NULL, 'fact', 'The Source Library groups sources into regulators, research institutions, national initiatives, global data portals and global indices.', 'تصنف مكتبة المصادر المصادر إلى جهات تنظيمية ومؤسسات بحثية ومبادرات وطنية ومنصات بيانات عالمية ومؤشرات عالمية.', NULL, NULL, NULL),
('01M4D6BHRHNY9DGGTTNVYCYTX6', NULL, 'fact', 'Every demo statistic in EnviroAI that is not sourced is labelled Illustrative so it is never mistaken for a published figure.', 'كل إحصاء توضيحي في EnviroAI غير موثق يوسم بأنه توضيحي حتى لا يختلط بالأرقام المنشورة.', NULL, NULL, NULL),
('01M4D6BHRH6Y70QVCESJ086GRK', NULL, 'fact', 'The delivery plan tracks more than 60 projects, each owned by a named delivery entity.', 'تتابع خطة التنفيذ أكثر من 60 مشروعاً، يملك كل منها جهة تنفيذ محددة.', NULL, NULL, NULL),
('01M4D6BHRHV7DH6T8BZXYCD6RB', NULL, 'fact', 'The Programme Office reviews monitoring and evaluation data against theme targets on a regular cycle.', 'يراجع مكتب البرنامج بيانات المتابعة والتقييم مقابل مستهدفات المحاور وفق دورة منتظمة.', NULL, NULL, NULL),
('01M4D6BHRHQJRK8X3ZVDQVPCSY', NULL, 'fact', 'The Environment Fund supports financing of environmental projects.', 'يدعم صندوق البيئة تمويل المشاريع البيئية.', NULL, NULL, NULL),
('01M4D6BHRKPBPKQV68BQRDJ60D', NULL, 'fact', 'The National Water Strategy 2030 frames the Kingdom''s long-term water agenda.', 'تؤطر الاستراتيجية الوطنية للمياه 2030 أجندة المملكة طويلة المدى في المياه.', NULL, NULL, NULL);
INSERT INTO "word_of_day" ("id", "date", "kind", "text_en", "text_ar", "attribution_en", "attribution_ar", "source_ref") VALUES
('01M4D6BHRMJFG1177DETS9H6MS', NULL, 'tip', 'Drag a PDF anywhere onto EnviroAI to upload it and start extracting insights instantly.', 'اسحب ملف PDF إلى أي مكان في EnviroAI لرفعه وبدء استخراج الرؤى فوراً.', NULL, NULL, NULL),
('01M4D6BHRM61PVGN3X13KP4SHV', NULL, 'tip', 'Press Ask to get answers with citations back to the original source documents.', 'اضغط على اسأل لتحصل على إجابات مع إحالات إلى الوثائق المصدرية الأصلية.', NULL, NULL, NULL),
('01M4D6BHRMRT638FF27N8S1R0F', NULL, 'tip', 'Follow topics that matter to your work to shape your For You feed.', 'تابع المواضيع المهمة لعملك لتشكيل صفحة المقترحات لك.', NULL, NULL, NULL),
('01M4D6BHRMQH5YHAGWPHF2DFVF', NULL, 'tip', 'Verify a machine translation into Arabic or English to earn Guardian points.', 'راجع ترجمة آلية إلى العربية أو الإنجليزية لتكسب نقاط الحارس.', NULL, NULL, NULL),
('01M4D6BHRMNQVFVK1HCA3B9SXB', NULL, 'tip', 'Use Institutional Memory search to filter documents by theme, topic or department.', 'استخدم بحث الذاكرة المؤسسية لتصفية الوثائق بحسب المحور أو الموضوع أو الإدارة.', NULL, NULL, NULL),
('01M4D6BHRMWE1S5MH8NVHG2EH4', NULL, 'tip', 'Bookmark a document to find it again quickly from your personal library.', 'ضع إشارة على وثيقة للعودة إليها بسرعة من مكتبتك الشخصية.', NULL, NULL, NULL),
('01M4D6BHRMT1WQ2QXM16PVM24V', NULL, 'tip', 'Open the Scorecard to explore indicators alongside their full metadata.', 'افتح بطاقة المؤشرات لاستعراض المؤشرات مع بياناتها الوصفية كاملة.', NULL, NULL, NULL),
('01M4D6BHRMT2G29XG232PANQTH', NULL, 'tip', 'Submit a bounty answer to help close a knowledge gap and earn recognition.', 'قدّم إجابة على مكافأة معرفية للمساعدة في سد فجوة معرفية وكسب التقدير.', NULL, NULL, NULL),
('01M4D6BHRM0TCWN2S7CMCVTRKZ', NULL, 'tip', 'Check your Impact Receipts to see how your contributions were cited elsewhere.', 'اطلع على إيصالات الأثر لترى كيف استُشهد بمساهماتك.', NULL, NULL, NULL),
('01M4D6BHRNVBYPEBZ7S6CEN799', NULL, 'tip', 'Use collections to browse curated sets of documents on a single theme.', 'استخدم المجموعات لتصفح مجموعات منتقاة من الوثائق حول محور واحد.', NULL, NULL, NULL),
('01M4D6BHRNCDR3HRJQW4574XY7', NULL, 'tip', 'Ask a follow-up question in the same thread to go deeper on a topic.', 'اطرح سؤالاً تالياً في المحادثة نفسها للتعمق في موضوع ما.', NULL, NULL, NULL),
('01M4D6BHRNF24X72FK40BX5J7G', NULL, 'tip', 'Rate an answer''s usefulness to help EnviroAI improve future responses.', 'قيّم فائدة الإجابة لمساعدة EnviroAI على تحسين الإجابات القادمة.', NULL, NULL, NULL),
('01M4D6BHRNP60GR3G726MF8E3K', NULL, 'tip', 'Add a note to any document to capture context for your team.', 'أضف ملاحظة إلى أي وثيقة لتوثيق السياق لفريقك.', NULL, NULL, NULL),
('01M4D6BHRNM2ZB681PEQYKA4GQ', NULL, 'tip', 'Check the Signals feed to see foresight trends that could affect your theme.', 'اطلع على تغذية الإشارات لتعرف اتجاهات الاستشراف التي قد تؤثر في محورك.', NULL, NULL, NULL),
('01M4D6BHRNPSMKDC6PS3ABCWTF', NULL, 'tip', 'Review the Risk Register regularly to keep mitigation plans current.', 'راجع سجل المخاطر بانتظام لإبقاء خطط المعالجة محدّثة.', NULL, NULL, NULL),
('01M4D6BHRNR5A0H1ET8AJ29EPN', NULL, 'tip', 'Use the Regulatory Overview to see which regulator owns a topic.', 'استخدم نظام البيئة لمعرفة الجهة التنظيمية المسؤولة عن موضوع ما.', NULL, NULL, NULL),
('01M4D6BHRNSMCYKWAYWN0D6H3Q', NULL, 'tip', 'Subscribe to a department''s updates to get notified when new documents land.', 'اشترك في مستجدات إدارة لتصلك إشعارات بالوثائق الجديدة.', NULL, NULL, NULL),
('01M4D6BHRNNAB0FEQ65EVPK28G', NULL, 'tip', 'Tag a colleague in a comment to bring them into a document discussion.', 'أشر إلى زميل في تعليق لإشراكه في نقاش حول وثيقة.', NULL, NULL, NULL),
('01M4D6BHRP41VCD15MYRHMA28M', NULL, 'tip', 'Check your Guardian points on your profile to see your verification streak.', 'اطلع على نقاط الحارس في ملفك لترى سلسلة التحقق لديك.', NULL, NULL, NULL),
('01M4D6BHRPCMY4GV1VB7QFD37N', NULL, 'tip', 'Use quick filters on the daily card to jump straight to indicators you follow.', 'استخدم المرشحات السريعة في البطاقة اليومية للانتقال مباشرة إلى المؤشرات التي تتابعها.', NULL, NULL, NULL);
